import{_ as e,c as t,o as r,a0 as i}from"./chunks/framework.DKRgXLPU.js";const _=JSON.parse('{"title":"Mental Game Exercise Worksheets","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/en/exercise-worksheets.md","filePath":"public/downloads/en/exercise-worksheets.md"}');const a=e({name:"public/downloads/en/exercise-worksheets.md"},[["render",function(e,_,a,o,n,s){return r(),t("div",null,[..._[0]||(_[0]=[i('<h1 id="mental-game-exercise-worksheets" tabindex="-1">Mental Game Exercise Worksheets <a class="header-anchor" href="#mental-game-exercise-worksheets" aria-label="Permalink to &quot;Mental Game Exercise Worksheets&quot;">​</a></h1><p><strong>Pétanque Academy - Practical Exercises</strong></p><hr><h2 id="exercise-1-flow-state-reflection" tabindex="-1">Exercise 1: Flow State Reflection <a class="header-anchor" href="#exercise-1-flow-state-reflection" aria-label="Permalink to &quot;Exercise 1: Flow State Reflection&quot;">​</a></h2><h3 id="when-have-you-experienced-flow" tabindex="-1">When Have You Experienced Flow? <a class="header-anchor" href="#when-have-you-experienced-flow" aria-label="Permalink to &quot;When Have You Experienced Flow?&quot;">​</a></h3><p>Think of a time when you played your best pétanque:</p><p><strong>Describe the situation:</strong></p><ul><li>What tournament/game was it?</li><li>What were the conditions?</li><li>Who were you playing with?</li></ul><hr><hr><p><strong>How did it feel?</strong></p><ul><li>What was your mental state?</li><li>How did time feel?</li><li>What were you thinking (or not thinking)?</li></ul><hr><hr><p><strong>What helped you get there?</strong></p><ul><li>What did you do before the game?</li><li>What was different about that day?</li><li>Can you recreate any of those conditions?</li></ul><hr><hr><hr><h2 id="exercise-2-inner-critic-inventory" tabindex="-1">Exercise 2: Inner Critic Inventory <a class="header-anchor" href="#exercise-2-inner-critic-inventory" aria-label="Permalink to &quot;Exercise 2: Inner Critic Inventory&quot;">​</a></h2><h3 id="identify-your-inner-critic" tabindex="-1">Identify Your Inner Critic <a class="header-anchor" href="#identify-your-inner-critic" aria-label="Permalink to &quot;Identify Your Inner Critic&quot;">​</a></h3><p><strong>What does your Inner Critic say?</strong></p><p>List 3-5 common critical thoughts you have during competition:</p><ol><li><hr></li><li><hr></li><li><hr></li><li><hr></li><li><hr></li></ol><p><strong>When does it appear?</strong></p><ul><li>After mistakes? □</li><li>Before important shots? □</li><li>When playing against strong opponents? □</li><li>When teammates are watching? □</li><li>Other: _______________________________________________</li></ul><hr><h2 id="exercise-3-reframing-practice" tabindex="-1">Exercise 3: Reframing Practice <a class="header-anchor" href="#exercise-3-reframing-practice" aria-label="Permalink to &quot;Exercise 3: Reframing Practice&quot;">​</a></h2><h3 id="transform-critic-to-coach" tabindex="-1">Transform Critic to Coach <a class="header-anchor" href="#transform-critic-to-coach" aria-label="Permalink to &quot;Transform Critic to Coach&quot;">​</a></h3><p><strong>For each Inner Critic thought, write an Inner Coach reframe:</strong></p><table tabindex="0"><thead><tr><th>Inner Critic</th><th>Inner Coach</th></tr></thead><tbody><tr><td>Example: &quot;I always mess up under pressure&quot;</td><td>&quot;I&#39;ve succeeded under pressure before, I can do it again&quot;</td></tr><tr><td>1. _________________________</td><td>_________________________</td></tr><tr><td>2. _________________________</td><td>_________________________</td></tr><tr><td>3. _________________________</td><td>_________________________</td></tr></tbody></table><p><strong>Practice saying these out loud</strong></p><hr><h2 id="exercise-4-pre-shot-routine-design" tabindex="-1">Exercise 4: Pre-Shot Routine Design <a class="header-anchor" href="#exercise-4-pre-shot-routine-design" aria-label="Permalink to &quot;Exercise 4: Pre-Shot Routine Design&quot;">​</a></h2><h3 id="create-your-personal-routine" tabindex="-1">Create Your Personal Routine <a class="header-anchor" href="#create-your-personal-routine" aria-label="Permalink to &quot;Create Your Personal Routine&quot;">​</a></h3><p>Design a 4-step pre-shot routine that works for you:</p><p><strong>Step 1: Visualize</strong></p><ul><li>What exactly will you visualize?</li><li>How long (2-3 seconds)?</li></ul><hr><p><strong>Step 2: Breathe</strong></p><ul><li>One deep breath or three?</li><li>Any specific pattern?</li></ul><hr><p><strong>Step 3: Anchor</strong></p><ul><li>What physical anchor will you use?</li><li>Touch boule? Specific stance?</li></ul><hr><p><strong>Step 4: Execute</strong></p><ul><li>What&#39;s your mental cue?</li><li>&quot;Trust&quot; / &quot;Flow&quot; / &quot;Go&quot;?</li></ul><hr><p><strong>Practice this routine 10 times today</strong></p><hr><h2 id="exercise-5-pressure-triggers" tabindex="-1">Exercise 5: Pressure Triggers <a class="header-anchor" href="#exercise-5-pressure-triggers" aria-label="Permalink to &quot;Exercise 5: Pressure Triggers&quot;">​</a></h2><h3 id="identify-your-pressure-points" tabindex="-1">Identify Your Pressure Points <a class="header-anchor" href="#identify-your-pressure-points" aria-label="Permalink to &quot;Identify Your Pressure Points&quot;">​</a></h3><p><strong>What situations create pressure for you?</strong></p><p>Rate each from 1 (no pressure) to 10 (extreme pressure):</p><ul><li>Playing against strong opponents: ___/10</li><li>Important tournament games: ___/10</li><li>Tied score, final shot: ___/10</li><li>After making a mistake: ___/10</li><li>When teammates are watching: ___/10</li><li>When I&#39;m playing poorly: ___/10</li><li>Other: _________________________ ___/10</li></ul><p><strong>For your highest-rated trigger:</strong></p><p>What physical sensations do you notice?</p><hr><p>What thoughts appear?</p><hr><p>Which technique will you use?</p><ul><li>[ ] 3-Breath Reset</li><li>[ ] Pre-shot routine</li><li>[ ] Reframing</li><li>[ ] Other: _____________________</li></ul><hr><h2 id="exercise-6-mode-switching-practice" tabindex="-1">Exercise 6: Mode Switching Practice <a class="header-anchor" href="#exercise-6-mode-switching-practice" aria-label="Permalink to &quot;Exercise 6: Mode Switching Practice&quot;">​</a></h2><h3 id="planning-vs-execution" tabindex="-1">Planning vs Execution <a class="header-anchor" href="#planning-vs-execution" aria-label="Permalink to &quot;Planning vs Execution&quot;">​</a></h3><p><strong>Practice the switch:</strong></p><p><strong>Planning Phase (Before shot):</strong></p><ul><li>What do I need to analyze?</li><li>What&#39;s my strategy?</li><li>What shot will I choose?</li></ul><p><strong>Execution Phase (During shot):</strong></p><ul><li>Clear your mind</li><li>Trust your body</li><li>Let it happen</li></ul><p><strong>Practice Exercise:</strong></p><p>Take 5 practice shots. For each:</p><ol><li>Spend 10 seconds in planning mode (analyze, decide)</li><li>Take 3 breaths to switch modes</li><li>Execute in flow mode (no thinking)</li></ol><p><strong>Reflection:</strong></p><ul><li>Could you feel the difference between modes?</li><li>Was the switch clear?</li><li>Which mode is harder for you?</li></ul><hr><hr><hr><h2 id="exercise-7-weekly-practice-plan" tabindex="-1">Exercise 7: Weekly Practice Plan <a class="header-anchor" href="#exercise-7-weekly-practice-plan" aria-label="Permalink to &quot;Exercise 7: Weekly Practice Plan&quot;">​</a></h2><h3 id="this-week-s-focus" tabindex="-1">This Week&#39;s Focus <a class="header-anchor" href="#this-week-s-focus" aria-label="Permalink to &quot;This Week&#39;s Focus&quot;">​</a></h3><p><strong>Choose ONE technique to practice:</strong></p><ul><li>[ ] 3-Breath Reset after every mistake</li><li>[ ] Pre-shot routine on every throw</li><li>[ ] Reframe one Inner Critic thought per session</li><li>[ ] Practice mode switching</li></ul><p><strong>Daily Practice:</strong></p><table tabindex="0"><thead><tr><th>Day</th><th>Practice Activity</th><th>Duration</th><th>Notes</th></tr></thead><tbody><tr><td>Mon</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Tue</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Wed</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Thu</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Fri</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sat</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sun</td><td>________________</td><td>___min</td><td>________________</td></tr></tbody></table><hr><h2 id="exercise-8-progress-tracking" tabindex="-1">Exercise 8: Progress Tracking <a class="header-anchor" href="#exercise-8-progress-tracking" aria-label="Permalink to &quot;Exercise 8: Progress Tracking&quot;">​</a></h2><h3 id="end-of-week-reflection" tabindex="-1">End of Week Reflection <a class="header-anchor" href="#end-of-week-reflection" aria-label="Permalink to &quot;End of Week Reflection&quot;">​</a></h3><p><strong>What did you practice this week?</strong></p><hr><p><strong>What did you notice?</strong></p><hr><hr><p><strong>What worked well?</strong></p><hr><hr><p><strong>What was challenging?</strong></p><hr><hr><p><strong>What will you continue next week?</strong></p><hr><hr><p><strong>What will you adjust?</strong></p><hr><hr><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><h3 id="continue-your-development" tabindex="-1">Continue Your Development <a class="header-anchor" href="#continue-your-development" aria-label="Permalink to &quot;Continue Your Development&quot;">​</a></h3><p><strong>Resources at carreau.app:</strong></p><ul><li>Goal Template - Structure your long-term development</li><li>Diary Template - Track daily progress</li><li>The Zone - Deep dive into flow states</li><li>Mental Strength - Advanced pressure management</li></ul><p><strong>Keep practicing:</strong></p><ul><li>Mental skills need consistent training</li><li>Start small, build gradually</li><li>Track your progress</li><li>Celebrate improvements</li></ul><hr><p><em>Pétanque Academy - Elite Player Development</em><br><em>carreau.app</em></p>',113)])])}]]);export{_ as __pageData,a as default};
